"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["11558"],{27140(e){e.exports=JSON.parse('{"id":"FIN-374","slug":"net-interest-income","term":"Net Interest Income","also_known_as":[],"difficulty":"Intermediate","definition":"Net interest income is the difference between the interest a bank earns on its loans and investments and the interest it pays on its deposits and borrowing.","explanation":["Net interest income is usually the largest source of income for traditional banks. It reflects the core business of borrowing money from depositors and lenders at one rate and lending or investing it at a higher rate.","For example, a bank that earns 90 million a year in interest on mortgages, business loans and bonds, and pays 40 million in interest to depositors and other lenders, has net interest income of 50 million.","Net interest income rises when a bank lends more, when the gap between loan and deposit rates widens or when interest-earning assets grow faster than interest-bearing liabilities. It falls when lending shrinks, when the gap narrows or when the bank must pay more to attract deposits.","Banks also earn non-interest income, such as fees for accounts, cards, advice and trading. Analysts look at both. Net interest income is often divided by average interest-earning assets to calculate the net interest margin, which allows comparison between banks of different sizes."],"note":"","total":1500,"prev":{"slug":"net-income-personal","term":"Net Income (Personal)"},"next":{"slug":"net-interest-margin","term":"Net Interest Margin (NIM)"}}')}}]);